// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes: module, agent tool and text diffs"
// Changes: The Changes view of a draft in one place. The editor provides the draft, its content and the current
//          project (ChangesProvider); every tab that shows a part drops in <ChangesToggle /> and, while it is on,
//          renders the changes module's output for that part (useChanges().changes) instead of its editor. One
//          on/off state for the whole draft, so it stays on when switching tabs. Text parts render as a git-style
//          line diff (<LineDiff />); the grid tabs (#8) use the same toggle and changes.

import { createContext, useContext, useDeferredValue, useMemo, useState, type ReactNode } from 'react'
import { draftChanges, type DiffLine, type DraftChanges, type LLConflict, type PartFlags } from '#/lib/changes'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes view for the grids"
// Changes: The grid tabs' Changes view – the changes module's output as the draft's grids with changed cells marked
//          ("old→new", an outline and hidden text; the cell detail line announces both values) – and added/removed
//          symbols, new/resolved LL conflicts and "no changes" as text.
import { changeGrids, type ChangeCell, type ChangeGrid, type ChangeGrids } from '#/lib/changeGrids'
import { readParts } from '#/lib/parts'
import type { ProjectData } from '#/lib/project'
import type { DraftRecord } from '#/server/projects.server'
import { LLGrid } from './LLGrid'
import { cx, ListTable, RowHeader } from './ui'

interface ChangesState {
  /** A draft is shown, so the Changes view exists. */
  available: boolean
  /** The Changes view is on. */
  show: boolean
  setShow: (show: boolean) => void
  /** The draft's changes against the current project; computed only while the view is on (null otherwise). */
  changes: DraftChanges | null
  /** The draft's grids with the changed cells marked (with `changes`). */
  grids: ChangeGrids | null
}

const ChangesContext = createContext<ChangesState>({ available: false, show: false, setShow: () => {}, changes: null, grids: null })

/**
 * Provides the Changes view for a draft: `content` is the draft as the editor shows it (its parts over the
 * project's naming and inputs), `project` the project's current content. Without a draft the view does not exist.
 */
export function ChangesProvider({
  draft,
  content,
  project,
  children,
}: {
  draft: DraftRecord | null
  content: ProjectData
  project: ProjectData
  children: ReactNode
}) {
  const [show, setShow] = useState(false)
  // Typing in a draft must not wait for the diff.
  const shown = useDeferredValue(content)
  const base = draft?.base.parts
  const changes = useMemo(
    () => (draft && show ? draftChanges({ draft: readParts(shown), project: readParts(project), base }) : null),
    [draft, show, shown, project, base],
  )
  const grids = useMemo(() => (changes ? changeGrids(readParts(shown), changes) : null), [changes, shown])
  const value = useMemo(() => ({ available: draft !== null, show: draft !== null && show, setShow, changes, grids }), [draft, show, changes, grids])
  return <ChangesContext value={value}>{children}</ChangesContext>
}

/** The Changes view state of the shown draft (available = false for a project). */
export const useChanges = () => useContext(ChangesContext)

/** The "Zmeny" switch of a draft tab; renders nothing outside a draft. */
export function ChangesToggle() {
  const { available, show, setShow } = useChanges()
  if (!available) return null
  return (
    <label className="inline-flex cursor-pointer items-center gap-2 rounded-full border border-white/10 bg-zinc-900/90 px-2.5 py-1 text-xs text-zinc-200 hover:border-indigo-400/50">
      {/* Native switch where supported (Safari), a checkbox elsewhere. */}
      <input type="checkbox" {...({ switch: '' } as object)} checked={show} onChange={(e) => setShow(e.target.checked)} className="m-0 accent-indigo-400" />
      Zmeny oproti projektu
    </label>
  )
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Spec #1 review fixes"
// Changes: A part changed only in the project says so (the draft did not change it; adopting cannot take it).
/** Changed / unchanged and "changed on both sides" of a part, as text. */
export function PartChangesNote({ flags, id }: { flags: PartFlags; id?: string }) {
  const projectOnly = flags.changed && flags.changedInDraft === false
  return (
    <p id={id} className="mb-2 text-xs text-zinc-400">
      {projectOnly
        ? 'Návrh túto časť nezmenil – zmenil ju projekt od vytvorenia návrhu. Prevzatie návrhu ju neprepíše.'
        : flags.changed
          ? 'Prevzatie návrhu by zmenilo túto časť projektu.'
          : 'Bez zmien – táto časť je rovnaká ako v projekte.'}
      {flags.changedOnBothSides && (
        <strong className="mt-1 block font-semibold text-amber-200">
          ⚠ Zmenené na oboch stranách: projekt sa v tejto časti od vytvorenia návrhu tiež zmenil.
        </strong>
      )}
    </p>
  )
}

const SIGN: Record<DiffLine['kind'], { sign: string; label: string; row: string }> = {
  same: { sign: '', label: '', row: 'text-zinc-300' },
  added: { sign: '+', label: 'pridaný riadok', row: 'diff-added' },
  removed: { sign: '−', label: 'odstránený riadok', row: 'diff-removed' },
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Spec #1 review fixes"
// Changes: `unchangedNote={false}` drops the "Bez zmien" line when a PartChangesNote above already says so.
/** A git-style line diff: line numbers in the project and the draft, +/− and the line; scrolls on its own. */
export function LineDiff({
  lines,
  label,
  className,
  unchangedNote = true,
}: {
  lines: DiffLine[]
  label: string
  className?: string
  /** Say "Bez zmien" when nothing was added or removed (off when the part's note already says it). */
  unchangedNote?: boolean
}) {
  const added = lines.filter((l) => l.kind === 'added').length
  const removed = lines.filter((l) => l.kind === 'removed').length
  return (
    <div className={cx('min-w-0', className)}>
      {(added > 0 || removed > 0 || unchangedNote) && (
        <p className="mb-1 text-xs text-zinc-400">
          {added || removed ? (
            <>
              <span className="text-emerald-300">+{added}</span> <span className="text-rose-300">−{removed}</span>{' '}
              <span className="sr-only">
                pridané riadky: {added}, odstránené riadky: {removed}
              </span>
            </>
          ) : (
            'Bez zmien'
          )}
        </p>
      )}
      {lines.length === 0 ? (
        <p className="rounded-xl border border-white/10 bg-black/40 px-3 py-2 text-xs text-zinc-400">Prázdne v projekte aj v návrhu.</p>
      ) : (
        <div role="region" aria-label={label} tabIndex={0} className="diff-region overflow-auto overscroll-contain rounded-xl border border-white/10 bg-black/40">
          <table className="diff w-full border-collapse font-mono text-[13px] leading-relaxed">
            <thead className="sr-only">
              <tr>
                <th scope="col">Riadok v projekte</th>
                <th scope="col">Riadok v návrhu</th>
                <th scope="col">Zmena</th>
                <th scope="col">Text</th>
              </tr>
            </thead>
            <tbody>
              {lines.map((line, i) => {
                const s = SIGN[line.kind]
                const text = line.text === '' ? ' ' : line.text
                return (
                  <tr key={i} className={s.row}>
                    <td className="diff-num">{line.oldLine ?? ''}</td>
                    <td className="diff-num">{line.newLine ?? ''}</td>
                    <td className="diff-sign">
                      <span aria-hidden="true">{s.sign}</span>
                      {s.label && <span className="sr-only">{s.label}</span>}
                    </td>
                    <td className="diff-text">{line.kind === 'added' ? <ins>{text}</ins> : line.kind === 'removed' ? <del>{text}</del> : text}</td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  )
}

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Spec #1 review fixes"
// Changes: Optional `name` for each row head (Predict rows are rule numbers: "č. 5", not a bare "5" that reads like a count).
/** Symbols (terminals, nonterminals) only one side has, as text. */
function SymbolChanges({
  grid,
  what,
  name = (s) => s,
}: {
  grid: ChangeGrid
  what: { added: string; removed: string }
  name?: (head: string) => string
}) {
  if (!grid.added.length && !grid.removed.length) return null
  return (
    <ul className="mb-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-zinc-300">
      {grid.added.length > 0 && (
        <li>
          <span aria-hidden="true" className="font-bold text-emerald-300">+ </span>
          {what.added}: <span className="font-mono">{grid.added.map(name).join(',  ')}</span>
        </li>
      )}
      {grid.removed.length > 0 && (
        <li>
          <span aria-hidden="true" className="font-bold text-rose-300">− </span>
          {what.removed}: <span className="font-mono">{grid.removed.map(name).join(',  ')}</span>
        </li>
      )}
    </ul>
  )
}

const changedCount = (grid: ChangeGrid) => grid.rows.reduce((n, r) => n + r.cells.filter((c) => c.change).length, 0)

const headMark = (grid: ChangeGrid) => (symbol: string) =>
  grid.added.includes(symbol) ? 'change-head change-head-added' : grid.removed.includes(symbol) ? 'change-head change-head-removed' : undefined

/**
 * A grid of the Changes view: the draft's table, changed cells as "old→new" with an outline and hidden "zmenené"
 * text; keyboard navigation and the detail line (which names both values) come from LLGrid.
 */
function ChangeGridTable({ grid, caption }: { grid: ChangeGrid; caption: string }) {
  const count = changedCount(grid)
  return (
    <>
      <p className="mb-2 text-xs text-zinc-400">
        Zmenené bunky: {count}. Bunka ukazuje <span className="font-mono">projekt→návrh</span> (∅ = prázdna).
      </p>
      <LLGrid
        model={grid}
        caption={caption}
        className="text-[13px]"
        headClass={headMark(grid)}
        mark={(_row, _col, cell) => ((cell as ChangeCell).change ? { className: 'change-cell', note: 'zmenené' } : undefined)}
      />
    </>
  )
}

/** The precedence table's Changes view: "no changes", or the grid with changed cells and terminals. */
export function PrecChangesView({ flags, grid }: { flags: PartFlags; grid: ChangeGrid }) {
  return (
    <>
      <PartChangesNote flags={flags} />
      {flags.changed && (
        <>
          <SymbolChanges grid={grid} what={{ added: 'Pridané terminály', removed: 'Odstránené terminály' }} />
          <ChangeGridTable grid={grid} caption="Precedenčná tabuľka – zmeny oproti projektu" />
        </>
      )}
    </>
  )
}

const conflictText = (c: LLConflict) => `[${c.nonterminal}, ${c.terminal}] – ${c.rules.map((r) => r.rule).join(', ')}`

/** The LL table's Changes view: "no changes", or the grid with changed cells, new and resolved conflicts. */
export function LLChangesView({ changes, grid }: { changes: DraftChanges['llTable']; grid: ChangeGrid }) {
  if (!changes.cells.length) return <p className="mb-2 text-xs text-zinc-400">Bez zmien – LL tabuľka je rovnaká ako v projekte.</p>
  return (
    <>
      <SymbolChanges grid={grid} what={{ added: 'Pridané neterminály', removed: 'Odstránené neterminály' }} />
      {(changes.newConflicts.length > 0 || changes.resolvedConflicts.length > 0) && (
        <ul className="mb-2 space-y-1 text-xs">
          {changes.newConflicts.length > 0 && (
            <li className="text-rose-200">
              <strong className="font-semibold">⚠ Nové konflikty:</strong> <span className="font-mono">{changes.newConflicts.map(conflictText).join('; ')}</span>
            </li>
          )}
          {changes.resolvedConflicts.length > 0 && (
            <li className="text-emerald-200">
              <strong className="font-semibold">✓ Vyriešené konflikty:</strong>{' '}
              <span className="font-mono">{changes.resolvedConflicts.map(conflictText).join('; ')}</span>
            </li>
          )}
        </ul>
      )}
      <ChangeGridTable grid={grid} caption="LL tabuľka – zmeny oproti projektu" />
    </>
  )
}

/** A changed value in a list table: the project's value struck out, then the draft's. */
function ChangedValue({ cell }: { cell: ChangeCell }) {
  if (!cell.change) return <>{cell.text}</>
  return (
    <span className="change-value">
      <span className="sr-only">zmenené, v projekte </span>
      <del>{cell.change.old || '∅'}</del>
      <span aria-hidden="true"> → </span>
      <span className="sr-only">, v návrhu </span>
      <ins>{cell.change.new || '∅'}</ins>
    </span>
  )
}

/** Empty/First/Follow or Predict in the Changes view: every row, changed values as project → draft. */
export function SetChangesView({
  grid,
  title,
  rows,
  rowName,
}: {
  grid: ChangeGrid
  title: string
  rows: string
  /** How a row head is named in the added/removed list (default: as is). */
  rowName?: (head: string) => string
}) {
  const changed = grid.rows.filter((r) => r.cells.some((c) => c.change))
  if (!changed.length) return <p className="text-xs text-zinc-400">Bez zmien – {title} sú rovnaké ako v projekte.</p>
  return (
    <>
      <p className="mb-2 text-xs text-zinc-400">
        Zmenené riadky: {changed.length}. Zmenená hodnota ukazuje <span className="font-mono">projekt → návrh</span>.
      </p>
      <SymbolChanges grid={grid} what={{ added: `Pridané ${rows}`, removed: `Odstránené ${rows}` }} name={rowName} />
      <ListTable head={grid.header} label={grid.title}>
        {grid.rows.map((r) => {
          const rowChanged = r.cells.some((c) => c.change)
          return (
            <tr key={r.head} className={cx(rowChanged && 'change-row')}>
              <RowHeader>
                {r.head}
                {rowChanged && <span className="sr-only"> (zmenené)</span>}
              </RowHeader>
              {r.cells.map((c, i) => (
                <td key={i} className={cx(c.change && 'change-cell')}>
                  <ChangedValue cell={c} />
                </td>
              ))}
            </tr>
          )
        })}
      </ListTable>
    </>
  )
}
